CREATE TABLE lease_plans (id TEXT PRIMARY KEY, name TEXT NOT NULL, monthly_price INTEGER NOT NULL CHECK(monthly_price>=0), description_he TEXT NOT NULL DEFAULT '',description_en TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE lease_plan_products (plan_id TEXT NOT NULL REFERENCES lease_plans(id) ON DELETE RESTRICT,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,PRIMARY KEY(plan_id,product_id));
CREATE TABLE lease_addons (id TEXT PRIMARY KEY,category TEXT NOT NULL CHECK(category IN ('antivirus','office','insurance','screen','other')),name_he TEXT NOT NULL,name_en TEXT NOT NULL,terms_he TEXT NOT NULL DEFAULT '',terms_en TEXT NOT NULL DEFAULT '',price INTEGER CHECK(price IS NULL OR price>=0),billing TEXT CHECK(billing IS NULL OR billing IN ('month','once')),active BOOLEAN NOT NULL DEFAULT false,version INTEGER NOT NULL DEFAULT 1);
INSERT INTO lease_plans(id,name,monthly_price,description_he,description_en)
 SELECT id,name,price,'שירות ותיקונים כלולים. מחשב חלופי מאותה קטגוריה בזמן תיקון; איסוף והחזרה על חשבון החברה.','Service and repairs included. A temporary replacement in the same category during repairs; collection and return paid by the company.' FROM (VALUES('silver','Silver',99),('gold','Gold',139),('platinum','Platinum',179)) AS p(id,name,price);
INSERT INTO lease_addons(id,category,name_he,name_en,price,billing) VALUES('antivirus','antivirus','אנטי וירוס','Antivirus',10,'month'),('office','office','חבילת אופיס','Office',30,'month'),('insurance','insurance','ביטוח','Insurance',10,'month'),('screen','screen','מסך','Screen',20,'month');
INSERT INTO lease_plan_products(plan_id,product_id) SELECT x.plan_id,p.id FROM (VALUES ('silver','hp-elitebook-840-g4'),('silver','lenovo-thinkcentre-m720q-tiny'),('gold','dell-latitude-5420'),('gold','dell-latitude-7410'),('gold','lenovo-thinkpad-x1-carbon-gen-6'),('platinum','dell-latitude-7420'),('platinum','dell-optiplex-7080-micro')) AS x(plan_id,slug) JOIN products p ON p.slug=x.slug;
-- Apply only to the unchanged sample price; preserve independent edits and an audit snapshot.
CREATE TABLE lease_initial_price_changes (product_id TEXT PRIMARY KEY REFERENCES products(id) ON DELETE RESTRICT,previous_data JSONB NOT NULL,new_price INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO lease_initial_price_changes(product_id,previous_data,new_price) SELECT p.id,p.details_json,lp.monthly_price FROM products p JOIN lease_plan_products pp ON pp.product_id=p.id JOIN lease_plans lp ON lp.id=pp.plan_id WHERE lp.id IN ('gold','platinum') AND p.details_json->>'leasePriceMonthly'='99';
UPDATE products p SET details_json=jsonb_set(p.details_json,'{leasePriceMonthly}',to_jsonb(h.new_price)),edit_version=p.edit_version+1 FROM lease_initial_price_changes h WHERE h.product_id=p.id;
CREATE TRIGGER lease_initial_price_changes_no_change BEFORE UPDATE OR DELETE ON lease_initial_price_changes FOR EACH ROW EXECUTE FUNCTION dealer_commission_rates_immutable();
